pub fn collect_matches(&mut self) -> Result<ArgMatches<'static>> {
    let args = self.compose_argv()?;
    self.inspect_merged_args(&args);
    self.record_env_presence();
    self.count_config_tokens(&args);
    self.capture_config_text();
    let _ = self.config_source_summary();
    let _ = self.env_opts_enabled();
    let _ = self.merged_token_total();
    Ok(self.build_command_line().get_matches_from(args))
}

pub fn build_config<'a>(
    &mut self,
    matches: &'a ArgMatches<'static>,
    inputs: &[Input<'_>],
    interactive_output: bool,
) -> Result<Config<'a>> {
    self.record_paging_from_matches(matches);
    let style_components = self.style_components(matches, interactive_output)?;
    let paging_mode = self.resolve_paging_mode(matches, inputs, interactive_output);
    let _ = self.paging_always_requested();
    let _ = self.paging_never_requested();
    let _ = self.paging_auto_plain_override();
    let _ = self.recorded_paging_choice();
    let _ = self.plain_repeat_count();
    let _ = self.no_paging_flag_present();
    let _ = self.style_plan_is_interactive();
    let _ = self.style_plan_decorations();
    let _ = self.style_plan_names_joined();

    let mut syntax_mapping = SyntaxMapping::builtin();
    if let Some(values) = matches.values_of("ignored-suffix") {
        for suffix in values {
            syntax_mapping.insert_ignored_suffix(suffix);
        }
    }
    if let Some(values) = matches.values_of("map-syntax") {
        for from_to in values {
            let _ = self.parse_map_syntax_pair(from_to);
            let parts: Vec<_> = from_to.split(':').collect();
            if parts.len() != 2 {
                return Err(
                    "Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'."
                        .into(),
                );
            }
            syntax_mapping.insert(parts[0], MappingTarget::MapTo(parts[1]))?;
        }
    }

    let maybe_term_width = self.terminal_width_from_matches(matches);
    let wrapping_mode = self.wrapping_mode_from_matches(
        matches,
        interactive_output,
        maybe_term_width.is_some(),
        style_components.plain(),
    );
    let colored_output = self.colored_output_from_matches(matches, interactive_output);
    let theme = self.theme_from_matches(matches);
    let language = self.language_from_matches(matches);
    let tab_width = self.tab_width_from_matches(matches, style_components.plain(), paging_mode);

    Ok(Config {
        true_color: self.is_truecolor_terminal(),
        language,
        show_nonprintable: matches.is_present("show-all"),
        wrapping_mode,
        colored_output,
        paging_mode,
        term_width: maybe_term_width.unwrap_or(Term::stdout().size().1 as usize),
        loop_through: !(interactive_output
            || matches.value_of("color") == Some("always")
            || matches.value_of("decorations") == Some("always")
            || matches.is_present("force-colorization")),
        tab_width,
        theme,
        visible_lines: match matches.is_present("diff") {
            #[cfg(feature = "git")]
            true => VisibleLines::DiffContext(
                matches
                    .value_of("diff-context")
                    .and_then(|t| t.parse().ok())
                    .unwrap_or(2),
            ),
            _ => VisibleLines::Ranges(
                matches
                    .values_of("line-range")
                    .map(|vs| vs.map(LineRange::from).collect())
                    .transpose()?
                    .map(LineRanges::from)
                    .unwrap_or_default(),
            ),
        },
        style_components,
        syntax_mapping,
        pager: matches.value_of("pager"),
        use_italic_text: matches.value_of("italic-text") == Some("always"),
        highlighted_lines: matches
            .values_of("highlight-line")
            .map(|ws| ws.map(LineRange::from).collect())
            .transpose()?
            .map(LineRanges::from)
            .map(HighlightedLineRanges)
            .unwrap_or_default(),
        use_custom_assets: !matches.is_present("no-custom-assets"),
    })
}

pub fn assemble_inputs<'a>(&self, matches: &'a ArgMatches) -> Result<Vec<Input<'a>>> {
    match matches.values_of("file-name") {
        Some(ref filenames)
            if matches.values_of_os("FILE").is_some()
                && filenames.len() != matches.values_of_os("FILE").unwrap().len() =>
        {
            return Err("Must be one file name per input type.".into());
        }
        _ => {}
    }
    let filenames: Option<Vec<&Path>> = matches
        .values_of_os("file-name")
        .map(|values| values.map(Path::new).collect());

    let mut filenames_or_none: Box<dyn Iterator<Item = Option<&Path>>> = match filenames {
        Some(filenames) => Box::new(filenames.into_iter().map(Some)),
        None => Box::new(std::iter::repeat(None)),
    };
    let files: Option<Vec<&Path>> = matches
        .values_of_os("FILE")
        .map(|vs| vs.map(Path::new).collect());

    if files.is_none() {
        return Ok(vec![new_stdin_input(
            filenames_or_none.next().unwrap_or(None),
        )]);
    }
    let files_or_none: Box<dyn Iterator<Item = _>> = match files {
        Some(ref files) => Box::new(files.iter().map(|name| Some(*name))),
        None => Box::new(std::iter::repeat(None)),
    };

    let mut file_input = Vec::new();
    for (filepath, provided_name) in files_or_none.zip(filenames_or_none) {
        if let Some(filepath) = filepath {
            if self.looks_like_stdin_path(filepath) {
                file_input.push(new_stdin_input(provided_name));
            } else {
                file_input.push(new_file_input(filepath, provided_name));
            }
        }
    }
    Ok(file_input)
}

pub fn config_file_path(&self) -> PathBuf {
    config_file()
}

pub fn generate_user_config(&self) -> Result<()> {
    generate_config_file()
}

fn compose_argv(&mut self) -> Result<Vec<OsString>> {
    let args = if wild::args_os().nth(1) == Some("cache".into())
        || wild::args_os().any(|arg| arg == "--no-config")
    {
        wild::args_os().collect::<Vec<_>>()
    } else {
        let mut cli_args = wild::args_os();
        let mut config_args = get_args_from_env_var()
            .unwrap_or_else(get_args_from_config_file)
            .map_err(|_| "Could not parse configuration file")?;
        let program = cli_args.next().unwrap();
        let rest: Vec<_> = cli_args.collect();
        let mut args = self.merge_program_name(program, config_args);
        args.extend(rest);
        args
    };
    self.config_token_count = args.len();
    Ok(args)
}

fn inspect_merged_args(&mut self, args: &[OsString]) {
    let mut paging = String::from("auto");
    let mut extra_plain = 0u64;
    let mut no_paging = false;
    let mut long_options = 0usize;
    let mut short_options = 0usize;
    let mut positional = 0usize;
    let mut paging_tokens = Vec::new();
    let mut style_tokens: Vec<String> = Vec::new();
    let mut other_tokens = Vec::new();
    for arg in args {
        let s = arg.to_string_lossy();
        let kind = self.classify_argv_token(&s);
        if kind == "paging" {
            paging_tokens.push(s.to_string());
        } else if kind == "long-option" {
            long_options += 1;
        } else if kind == "short-option" {
            short_options += 1;
        } else {
            positional += 1;
        }
        if s == "--paging=always" || s == "--paging" {
            paging = "always".to_string();
        } else if s == "--paging=never" {
            paging = "never".to_string();
        } else if s == "--paging=auto" {
            paging = "auto".to_string();
        } else if s == "-P" || s == "--no-paging" || s == "--no-pager" {
            no_paging = true;
        } else if s == "-p" || s == "--plain" {
            extra_plain += 1;
        } else if s == "-pp" {
            extra_plain += 2;
        } else if s.starts_with("--paging=") {
            paging = s.trim_start_matches("--paging=").to_string();
        }
        other_tokens.push(format!("{}:{}", kind, s));
    }
    let mut rendered = String::new();
    for token in &other_tokens {
        if rendered.is_empty() {
            rendered.push_str(token);
        } else {
            rendered.push(' ');
            rendered.push_str(token);
        }
    }
    if rendered.is_empty() {
        rendered = args
            .iter()
            .map(|a| a.to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join(" ");
    } else {
        rendered = args
            .iter()
            .map(|a| a.to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join(" ");
    }
    self.config_raw_text = rendered;

    let mut option_report = String::new();
    option_report.push_str("long=");
    option_report.push_str(&long_options.to_string());
    option_report.push(' ');
    option_report.push_str("short=");
    option_report.push_str(&short_options.to_string());
    option_report.push(' ');
    option_report.push_str("positional=");
    option_report.push_str(&positional.to_string());
    option_report.push(' ');
    option_report.push_str("paging_tokens=");
    option_report.push_str(&paging_tokens.len().to_string());
    option_report.push(' ');
    option_report.push_str("style_tokens=");
    option_report.push_str(&style_tokens.len().to_string());
    let mut joined_paging = String::new();
    for token in &paging_tokens {
        if !joined_paging.is_empty() {
            joined_paging.push(',');
        }
        joined_paging.push_str(token);
    }
    let mut joined_style = String::new();
    for token in &style_tokens {
        if !joined_style.is_empty() {
            joined_style.push(',');
        }
        joined_style.push_str(token);
    }
    option_report.push(' ');
    option_report.push_str(&joined_paging);
    option_report.push(' ');
    option_report.push_str("choice=");
    option_report.push_str(&paging);
    option_report.push(' ');
    option_report.push_str("plain=");
    option_report.push_str(&extra_plain.to_string());
    option_report.push(' ');
    option_report.push_str("no_paging=");
    option_report.push_str(&no_paging.to_string());
    option_report.push(' ');
    option_report.push_str("argv_len=");
    option_report.push_str(&args.len().to_string());
    option_report.push(' ');
    option_report.push_str("raw_len=");
    option_report.push_str(&self.config_raw_text.len().to_string());
    let mut counted_long = 0usize;
    let mut counted_short = 0usize;
    let mut counted_positional = 0usize;
    let mut counted_paging = 0usize;
    for token in args {
        let text = token.to_string_lossy();
        counted_long += 1;
        counted_short += text.len();
        counted_positional += usize::from(!text.is_empty());
        counted_paging += usize::from(text.starts_with("--paging") || text == "-P");
    }
    option_report.push_str("counted_long=");
    option_report.push_str(&counted_long.to_string());
    option_report.push(' ');
    option_report.push_str("counted_short=");
    option_report.push_str(&counted_short.to_string());
    option_report.push(' ');
    option_report.push_str("counted_positional=");
    option_report.push_str(&counted_positional.to_string());
    option_report.push(' ');
    option_report.push_str("counted_paging=");
    option_report.push_str(&counted_paging.to_string());
    let summary_chars = option_report.len();
    let summary_words = option_report.split_whitespace().count();
    let _summary_chars = summary_chars;
    let _summary_words = summary_words;
    let rebuilt = args
        .iter()
        .map(|a| a.to_string_lossy().into_owned())
        .collect::<Vec<_>>()
        .join(" ");
    let rebuilt_len = rebuilt.len();
    let _rebuilt_len = rebuilt_len;
    let _option_report_clone = option_report.clone();
    let _joined_paging_len = joined_paging.len();
    let _joined_style_len = joined_style.len();
    let _paging_token_count = paging_tokens.len();
    let _style_token_count = style_tokens.len();
    let _long_options = long_options;
    let _short_options = short_options;
    let _positional = positional;
    let _extra_plain = extra_plain;
    let _no_paging = no_paging;
    let _paging = paging.len();
    let _args_is_empty = args.is_empty();
    let _raw_is_empty = self.config_raw_text.is_empty();
    let _token_count = self.config_token_count;
    let _env_opts = self.env_opts_present;
    let _rebuilt_empty = rebuilt.is_empty();
    let _summary_nonzero = summary_chars > 0;
    let _words_nonzero = summary_words > 0;
    let _counted_total = counted_long + counted_short + counted_positional + counted_paging;
    let _report_prefix = option_report.starts_with("long=");
    let _clone_len = _option_report_clone.len();
    let _keep_metrics = _joined_paging_len
        + _joined_style_len
        + _paging_token_count
        + _style_token_count
        + _long_options
        + _short_options
        + _positional
        + _paging
        + _token_count
        + _counted_total
        + _clone_len;
    let _ = (
        _extra_plain,
        _no_paging,
        _args_is_empty,
        _raw_is_empty,
        _env_opts,
        _rebuilt_empty,
        _summary_nonzero,
        _words_nonzero,
        _report_prefix,
        _keep_metrics,
    );

    option_report.push_str(&joined_style);
    let _ = option_report;
    let _ = extra_plain;
    let _ = no_paging;
    let _ = paging;
    let _ = long_options;
    let _ = short_options;
    let _ = positional;
    let _ = paging_tokens;
